import { createLifecycleTestKit } from '@nocobase/lifecycle/testing';
import { beforeEach, describe, expect, it } from 'vitest';

import {
  ticketLifecycle,
  type TicketNotification,
  type TicketNotifier,
} from '../../server/it-service-desk/lifecycle.js';

class FakeNotifier implements TicketNotifier {
  public readonly calls: TicketNotification[] = [];

  public async notify(input: TicketNotification): Promise<void> {
    this.calls.push(input);
  }
}

function createKit() {
  const notify = new FakeNotifier();
  const kit = createLifecycleTestKit(ticketLifecycle, {
    services: { notify },
  });
  return { kit, notify };
}

const BASE = {
  title: 'Printer jams',
  description: 'The third-floor printer jams on every job.',
  urgency: 'normal' as const,
  reporterId: 'employee',
};

describe('tickets lifecycle', () => {
  let kit: ReturnType<typeof createKit>['kit'];
  let notify: FakeNotifier;

  beforeEach(() => {
    ({ kit, notify } = createKit());
  });

  it('runs a ticket from creation to closure and notifies each handover', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });
    expect(kit.get(ticket).status).toBe('pending');

    await kit.fire(ticket, 'assign', { assigneeId: 'engineer' }, { actor: 'service' });
    expect(kit.get(ticket).status).toBe('processing');
    expect(kit.get(ticket).assigneeId).toBe('engineer');
    expect(kit.get(ticket).assignedAt).toBeTruthy();

    await kit.fire(
      ticket,
      'progress',
      { handlingNote: 'Cleared the jam and replaced the roller.' },
      { actor: 'engineer' },
    );
    await kit.fire(
      ticket,
      'resolve',
      { solution: 'Roller replaced; test pages print.' },
      { actor: 'engineer' },
    );
    expect(kit.get(ticket).status).toBe('resolved');

    await kit.fire(ticket, 'confirm', {}, { actor: 'employee' });
    expect(kit.get(ticket).status).toBe('closed');
    expect(kit.get(ticket).closedAt).toBeTruthy();

    expect(await kit.history(ticket)).toEqual([
      '$create',
      'assign',
      'progress',
      'resolve',
      'confirm',
    ]);
    expect(notify.calls.map((call) => call.event)).toEqual([
      'assigned',
      'resolved',
      'closed',
    ]);
  });

  it('reopens a resolved ticket when the reporter returns it', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });
    await kit.fire(ticket, 'assign', { assigneeId: 'engineer' });
    await kit.fire(ticket, 'resolve', { solution: 'Rebooted.' });

    await kit.fire(
      ticket,
      'return',
      { lastReturnReason: 'It broke again this morning.' },
      { actor: 'employee' },
    );

    expect(kit.get(ticket).status).toBe('processing');
    expect(kit.get(ticket).returnedCount).toBe(1);
    expect(kit.get(ticket).resolvedAt).toBeNull();
    expect(notify.calls.map((call) => call.event)).toEqual([
      'assigned',
      'resolved',
      'returned',
    ]);
  });

  it('refuses a resolution with no solution and a return with no reason', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });
    await kit.fire(ticket, 'assign', { assigneeId: 'engineer' });

    await expect(kit.fire(ticket, 'resolve', {}, { actor: 'engineer' })).rejects.toMatchObject(
      { code: 'INVALID_INPUT' },
    );
    expect(kit.get(ticket).status).toBe('processing');

    await kit.fire(ticket, 'resolve', { solution: 'Fixed.' });
    await expect(
      kit.fire(ticket, 'return', {}, { actor: 'employee' }),
    ).rejects.toMatchObject({ code: 'INVALID_INPUT' });
    expect(kit.get(ticket).status).toBe('resolved');
  });

  it('refuses a transition the current state does not allow', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });
    await expect(kit.fire(ticket, 'confirm', {})).rejects.toMatchObject({
      code: 'INVALID_STATE',
    });
  });

  it('refuses the system-only reminder from a person', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });
    await expect(
      kit.runtime.fire('tickets', ticket.id, 'remind', {
        actor: { id: 'service' },
        manual: true,
      }),
    ).rejects.toMatchObject({ code: 'NOT_MANUAL' });
  });

  it('reminds the service desk once a ticket has idled past the threshold', async () => {
    const ticket = await kit.start(BASE, { actor: 'employee' });

    await kit.runTriggers();
    expect(notify.calls).toHaveLength(0);

    kit.advance({ hours: 25 });
    await kit.runTriggers();

    expect(kit.get(ticket).status).toBe('pending');
    expect(kit.get(ticket).remindedAt).toBeTruthy();
    expect(notify.calls.map((call) => call.event)).toEqual(['overdue']);
    // The reminder is a self-transition, so the next one waits another interval.
    expect(await kit.history(ticket)).toEqual(['$create', 'remind']);
  });
});
